 "content": "from collections import deque


def transform(grid):
    """Recolor each color-1 component to the color of an identical-shaped exemplar."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            min_r = min(x for x, _ in cells)
            min_c = min(y for _, y in cells)
            shape = frozenset((x - min_r, y - min_c) for x, y in cells)
            components.append((color, cells, shape))

    exemplars = {}
    for color, _, shape in components:
        if color != 1:
            exemplars.setdefault(shape, color)

    out = [row[:] for row in grid]
    for color, cells, shape in components:
        if color == 1 and shape in exemplars:
            replacement = exemplars[shape]
            for r, c in cells:
                out[r][c] = replacement
    return out
